    public void Official_case(string file, int groupIndex, int testIndex, string groupDescription, string testDescription)
    {
        var fixture = Path.Combine(FixtureRoot(), "tests", "draft2020-12", file);
        using var document = JsonDocument.Parse(File.ReadAllBytes(fixture));
        var group = document.RootElement[groupIndex];
        var test = group.GetProperty("tests")[testIndex];
        // Detect stale indexes or altered descriptions instead of silently running a different case.
        Assert.Equal(groupDescription, group.GetProperty("description").GetString());
        Assert.Equal(testDescription, test.GetProperty("description").GetString());
        var schemas = new JsonSchemas().Add("suite.schema.json", group.GetProperty("schema").GetRawText());
        Assert.NotNull(schemas.Find("suite.schema.json"));
        var issues = schemas.Validate(test.GetProperty("data"), "suite.schema.json");
        var expected = test.GetProperty("valid").GetBoolean();
        Assert.True((issues.Count == 0) == expected,
            $"{file} [{groupIndex}:{testIndex}] {groupDescription} / {testDescription}: expected valid={expected}; actual valid={issues.Count == 0}; issues={string.Join("; ", issues)}");
    }

    private static string FixtureRoot()
    {
        for (var dir = new DirectoryInfo(AppContext.BaseDirectory); dir is not null; dir = dir.Parent)
        {
            var path = Path.Combine(dir.FullName, "fixtures", "json-schema-suite");
            if (Directory.Exists(path)) return path;
        }
        throw new DirectoryNotFoundException("Cannot find fixtures/json-schema-suite above the test assembly.");
    }
